      delegationDepth: 2,
    })
    await scaffold.ctx.sessionPersistence.append(grandchildId, [
      {
        type: 'turn/start',
        seq: 0,
        time: authoredAt,
        data: { turn: 1, trigger: { kind: 'message', source: { kind: 'user' } } },
      },
      {
        type: 'user/message',
        seq: 1,
        time: authoredAt + 1,
        data: {
